// AI: below section was generated by an AI
/*
 * Home Gadgets usermod
 * --------------------
 * Turns a WLED ESP32 into a small home controller:
 *  - 8 relay outputs for home appliances (active LOW or HIGH, power-on state, auto-off timer)
 *  - 8 wall switch inputs: dry contacts (switch to GND) or existing mains switches connected
 *    through AC opto-isolator modules (these output a pulse train at mains frequency)
 *  - 2 PIR motion sensors, each with its own list of up to 8 actions and a "turn back off" timer
 *  - "Moods": ready-made LED looks (effect + palette + speed + brightness) that can be applied
 *    to LED 1, LED 2 or both. Users can save the current look of a strip as a new mood.
 *  - Scenes: one tap runs a list of up to 8 actions (relays + moods)
 *  - A mobile-friendly page at http://<device>/home and plain HTTP links for Siri Shortcuts
 *
 * Design notes:
 *  - Configuration lives in /home.json, not in cfg.json. It contains nested lists (actions, moods)
 *    that the generic usermod settings page cannot edit; saving that page would corrupt them.
 *  - Web requests run in the AsyncTCP task. They never touch hardware directly: commands go through
 *    a FreeRTOS queue and configuration uploads are handed over to loop(), so all GPIO, segment
 *    and file system changes happen in the main loop.
 *  - Mains appliances need more protection than LEDs: WLED sends "Access-Control-Allow-Origin: *" on
 *    every response, so any web page opened on a phone in the same network could send commands.
 *    A random API key (generated on the device) is therefore required for everything that can switch
 *    a relay (/home/api, relay/scene/all-off commands in /json/state) and for saving the configuration.
 *    The key is only delivered in a response without that header, so other web sites cannot read it.
 *    LED-only commands (moods, strips, microphone) stay open like the rest of WLED's JSON API.
 *    Saving the configuration additionally requires WLED's settings PIN if one is set.
 */

// ----- limits -----
constexpr uint8_t  HG_RELAYS        = 8;
constexpr uint8_t  HG_SWITCHES      = 8;
constexpr uint8_t  HG_SENSORS       = 2;
constexpr uint8_t  HG_ACTIONS       = 8;    // actions per motion sensor / scene
constexpr uint8_t  HG_SCENES        = 6;
constexpr uint8_t  HG_CUSTOM_MOODS  = 12;
constexpr uint8_t  HG_STRIPS        = 2;    // "LED 1" and "LED 2", each mapped to a WLED segment
constexpr size_t   HG_NAME_LEN      = 24;   // user visible names, including terminating NUL
constexpr size_t   HG_FXNAME_LEN    = 33;   // effect / palette names, including terminating NUL
constexpr uint8_t  HG_MOOD_CUSTOM_BASE = 100; // mood ids >= 100 address custom moods
constexpr uint8_t  HG_ICON_COUNT    = 16;   // number of appliance icons known by the web page
constexpr uint8_t  HG_QUEUE_LEN     = 16;
constexpr uint8_t  HG_CMDS_PER_LOOP = 8;
constexpr size_t   HG_MAX_CFG_BODY  = 12288; // max. size of an uploaded configuration
constexpr size_t   HG_KEY_LEN       = 10;   // API key characters (without terminating NUL)
static const char  HG_KEY_CHARS[]   = "abcdefghjkmnpqrstuvwxyz23456789"; // no easily confused characters

// ----- timing -----
constexpr uint16_t HG_DRY_DEBOUNCE_MS = 50;   // dry contact wall switch
constexpr uint16_t HG_AC_HOLD_MS      = 60;   // AC opto modules pulse every 10/20 ms: "on" while a pulse was seen within this window
constexpr uint16_t HG_AC_DEBOUNCE_MS  = 100;  // must be longer than HG_AC_HOLD_MS
constexpr uint16_t HG_PIR_DEBOUNCE_MS = 50;
constexpr uint16_t HG_SETTLE_MS       = 1000; // after boot / re-configuration inputs are read but do not trigger anything
constexpr uint16_t HG_AUDIO_APPLY_MS  = 3000; // re-apply stored microphone settings this long after boot
constexpr uint32_t HG_STATE_SAVE_DELAY_MS = 3000; // relay "last state" is written this long after the last change
constexpr uint32_t HG_CFG_SAVE_DELAY_MS   = 3000; // microphone settings are written this long after the last change
constexpr uint16_t HG_RESTORE_STEP_MS = 400;  // after boot, relays that should be on are switched on one by one (inrush current)
constexpr uint32_t HG_KEY_GEN_DELAY_MS = 5000; // the API key is generated once Wi-Fi runs (hardware RNG is only truly random with RF enabled)
constexpr uint16_t HG_HOLD_MIN_S      = 5;
constexpr uint16_t HG_HOLD_MAX_S      = 3600;
constexpr uint16_t HG_AUTO_OFF_MAX_MIN = 1440;

// debug id for WLED's global JSON buffer lock (only printed in debug builds)
constexpr uint8_t  HG_JSON_LOCK_ID = 59;

static const char HG_CFG_FILE[]   = "/home.json";
static const char HG_CFG_TMP[]    = "/home.tmp";
static const char HG_STATE_FILE[] = "/hgstate.json";
// the API key lives in its own file: WLED's static file server refuses paths containing "sec" and the
// /edit file manager hides names containing "wsec.json", so neither can hand the key to other web sites
static const char HG_KEY_FILE[]   = "/hgwsec.json";
static const char HG_KEY_TMP[]    = "/hgwsec.json.tmp";

// default wiring for a 38-pin ESP32 DevKit (see readme.md)
static const int8_t HG_DEFAULT_RELAY_PINS[HG_RELAYS]    = {4, 13, 18, 19, 23, 25, 26, 27};
static const int8_t HG_DEFAULT_SWITCH_PINS[HG_SWITCHES] = {14, 32, 33, 21, 22, 5, 15, 35};
