// ----- actions -----
enum HgActionType : uint8_t {
  ACT_NONE = 0,
  ACT_RELAY_ON,       // target = relay index
  ACT_RELAY_OFF,
  ACT_RELAY_TOGGLE,
  ACT_MOOD,           // target = mood id, strips = LED mask
  ACT_STRIP_ON,       // strips = LED mask
  ACT_STRIP_OFF,
  ACT_ALL_RELAYS_OFF,
  ACT_COUNT
};

struct HgAction {
  uint8_t type;
  uint8_t target;
  uint8_t strips;     // bit 0 = LED 1, bit 1 = LED 2
};

// ----- commands queued from web requests / JSON API to loop() -----
enum HgCmdType : uint8_t { CMD_RELAY, CMD_MOOD, CMD_SCENE, CMD_STRIP, CMD_ALL_OFF, CMD_MIC, CMD_LEVEL };
struct HgCmd {
  uint8_t type;
  uint8_t a;
  uint8_t b;
};
constexpr uint8_t HG_RELAY_TOGGLE = 2; // CMD_RELAY: b = 0 off, 1 on, 2 toggle

// ----- hardware objects -----
struct HgRelay {
  char     name[HG_NAME_LEN];
  int8_t   pin;
  uint8_t  icon;
  bool     activeLow;   // most 5 V relay boards switch on when their input is pulled LOW
  bool     keep;        // "stays on": scenes, motion sensors and "all off" never switch it off (fridge, aquarium)
  uint8_t  powerOn;     // state after boot: 0 = off, 1 = on, 2 = last state
  uint16_t autoOffMin;  // switch off automatically after this many minutes, 0 = never
  // runtime
  bool     state;
  bool     allocated;
  uint8_t  pinError;    // 0 = ok, 1 = not a usable pin, 2 = pin used by something else
  uint32_t onSince;
};

enum HgSwitchType : uint8_t { SW_DRY = 0, SW_AC = 1 };
enum HgSwitchMode : uint8_t { SW_TOGGLE = 0, SW_FOLLOW = 1 };

struct HgSwitch {
  int8_t   pin;
  uint8_t  type;        // HgSwitchType
  uint8_t  mode;        // HgSwitchMode
  int8_t   relay;       // relay controlled by this switch, -1 = none
  bool     invert;      // input is active HIGH instead of active LOW
  // runtime
  bool     allocated;
  uint8_t  pinError;
  bool     state;       // debounced state
  bool     rawPrev;
  uint32_t rawSince;
};

struct HgSensor {
  char     name[HG_NAME_LEN];
  int8_t   pin;
  bool     enabled;
  bool     nightOnly;   // only react between sunset and sunrise
  bool     undo;        // switch things back off when the hold time has passed
  uint16_t holdSec;     // seconds without motion before "undo"
  HgAction actions[HG_ACTIONS];
  // runtime
  bool     allocated;
  uint8_t  pinError;
  bool     motion;
  bool     rawPrev;
  uint32_t rawSince;
  bool     active;      // actions have run and the hold timer is running
  uint32_t lastMotion;
};

struct HgScene {
  char     name[HG_NAME_LEN];
  HgAction actions[HG_ACTIONS];
};

// a mood captured from a segment ("Save current look")
struct HgMood {
  bool     used;
  int8_t   replaces;    // index of the built-in mood this one overrides, -1 = additional mood
  char     name[HG_NAME_LEN];
  char     fx[HG_FXNAME_LEN];  // effect / palette are stored by name, so moods survive
  char     pal[HG_FXNAME_LEN]; // effect list changes in future WLED versions
  uint8_t  fxId, palId;        // fallback if a name cannot be found anymore
  uint8_t  sx, ix, c1, c2, c3, bri;
  uint32_t col[3];
};

// built-in moods; effect and palette names must match WLED's effect and palette lists
struct HgBuiltinMood {
  const char *name;
  const char *fx;
  const char *pal;      // "" = use the effect's default palette
  uint8_t     sx, ix, bri;
  uint32_t    col[3];   // segment colors
  uint32_t    preview[3]; // gradient shown on the web page
  bool        sound;    // needs the microphone
};

